const fs = require('node:fs');

function loadConfig(filePath, defaults = {}) {
  let parsed = {};
  try {
    parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }
  return { ...defaults, ...parsed };
}

module.exports = { loadConfig };
